def toc_handler(element, md):
    if isinstance(element, md.models.html.Heading):
        level = element.tag[1:]
        if min_level <= int(level) <= max_level:
            if heading_id:
                id = heading_id(element)
            else:
                id = element.get('id')
            toc.append({'level': level, 'id': id, 'text': striptags(element.text)})

