    ext=toc_processor,
    toc_handler=toc_handler,
    toc_level=toc_level,
    toc=toc,
)

def toc_tree(tree, level, toc):
    for child in tree:
        if child.tag == 'h%s' % level:
            heading_id = child.get('id')
            if not heading_id:
                if heading_id is None:
                    heading_id = lambda x: x
                heading_id = heading_id(striptags(child.text))
                child.set('id', heading_id)
            toc.append((heading_id, child.text))
            toc_tree(child, level + 1, toc)

def toc_extension(md, min_level, max_level, heading_id):
    toc = []
    toc_tree(md.tree, min_level, toc)
    md.env['toc'] = toc

