def toc_hook(md, buf, code):

    """
    This function is a hook to save table of contents (TOC) items into the state.env. It is usually helpful for doc generator.
    Input-Output Arguments
    :param md: Markdown instance. The instance of the Markdown class.
    :param buf: List. A list of lines of the document.
    :param code: String. The code block.
    :return: No return values.
    """

    if code.startswith('#'):

        if min_level <= len(code.split('#')) <= max_level:

            if heading_id:
                heading_id = heading_id(code)
            else:
                heading_id = code.strip('#').strip()

            md.state.env['toc'].append({
                'heading_id': heading_id,
                'heading_text': striptags(code)
            })

md.registerExtension('toc', toc_hook)

