if any(isinstance(el, list) for el in hue):
    hue = list(itertools.chain(*hue))

# get the unique categories in the hue
hue_set = list(sorted(set(hue), key=list(hue).index))

# get the unique categories in the labels
if labels is not None:
    labels_set = list(sorted(set(labels), key=list(labels).index))
else:
    labels_set = None

# reshape the input data based on the categories in the hue
