    x_reshaped.append(np.array(x)[np.array(hue) == i])

# reshape the labels based on the categories in the hue
if labels is not None:
    labels_reshaped = []
    for i in hue_set:
        labels_reshaped.append(np.array(labels)[np.array(hue) == i])
