def decorator(func: Callable) -> Callable:
    """
    This is the inner function of the decorator. It takes a function as input and returns a wrapped version of the function that emits a warning when called.
    Input-Output Arguments
    :param func: Callable. The function to be wrapped.
    :return: Callable. The wrapped function that emits a warning when called.
    """

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        warnings.warn(f"{func.__name__} is deprecated. {reason}", DeprecationWarning, stacklevel=2)
        return func(*args, **kwargs)

    return wrapper

return decorator

