class SignalAwaiter:
    def __init__(self, signals):
        self._signals = signals
        self._awaited_signals = {}
        self._awaited_signals = weakref.WeakKeyDictionary()

    def __await__(self):
        for signal in self._signals:
            self._awaited_signals[signal] = signal.connect(self._on_signal, signal.STRONG)
        return self._await

    def _on_signal(self, signal, args, kwargs):
        if args:
            self._awaited_signals[signal] = args[0]
            for token in self._awaited_signals.values():
                signal.disconnect(token)
            self._awaited_signals.clear()
            return True
        return False

