def render_attributes(attributes):
  """
  Render the attributes of the tag.
  Input-Output Arguments
  :param attributes: Dict. A dictionary of attributes.
  :return: String. The rendered output of the attributes.
  """
  if attributes:
    return ' ' + ' '.join(
        '%s="%s"' % (util.escape(attr), util.escape(value))
        for attr, value in attributes.items()
    )
  return ''

def render_children(children, indent, pretty):
  """
  Render the children of the tag.
  Input-Output Arguments
  :param children: List. A list of children.
  :param indent: String. The string used for indentation.
  :param pretty: Bool. Whether to add line breaks and indentation for a prettier output.
  :return: String. The rendered output of the children.
  """
  if not children:
    return ''

  if pretty:
    return '\n' + indent + indent.join(
        str(child) for child in children
    ) + '\n' + indent
  else:
    return ''.join(str(child) for child in children)

