def fixup(m):
  text = m.group(0)
  if text[:2] == "&#":
    try:
      if text[:3] == "&#x":
        return unichr(int(text[3:-1], 16))
      else:
        return unichr(int(text[2:-1]))
    except ValueError:
      pass
  else:
    try:
      text = unichr(_unescape[text[1:-1]])
    except KeyError:
      pass
  return text  # leave as is
return re.sub("&#?\w+;", fixup, data)

def unescape_match(match):
  entity = match.group(1)
  if entity.startswith('#'):
    return chr(int(entity[1:]))
  else:
    return chr(_unescape[entity])

return re.sub(r'&([^;]+);', unescape_match, data)

def replace(match):
  return unichr(_unescape[match.group(1)])

return re.sub(r'&(\w+);', replace, data)

