# The format for the BatchGet is as follows:
# {
#     'RequestItems': {
#         'TableName': {
#             'Keys': [
#                 {
#                     'HashKeyElement': {
#                         'S': 'string'
#                     },
#                     'RangeKeyElement': {
#                         'S': 'string'
#                     }
#                 },
#             ],
#             'AttributesToGet': [
#                 'string',
#             ],
#             'ConsistentRead': True|False
#         },
#     }
# }
# The format for the BatchWrite is as follows:
# {
#     'RequestItems': {
#         'TableName': [
#             {
#                 'PutRequest': {
#                     'Item': {
#                         'AttributeName': {
#                             'S': 'string',
#                             'N': 'string',
#                             'B': b'bytes',
#                             'SS': [
#                                 'string',
#                             ],
#                             'NS': [
#                                 'string',
#                             ],
#                             'BS': [
#                                 b'bytes',
#                             ],
#                             'M': {
#                                 'string': {'... recursive ...'}
#                             },
#                             'L': [
#                                 {'... recursive ...'},
#                             ],
#                             'NULL': True|False,
#                             'BOOL': True|False
#                         }
#                     }
#                 },
#             },
#         ],
#     }
# }
# The format for the BatchDelete is as follows:
# {
#     'RequestItems': {
#         'TableName': [
