    if isinstance(recipe, (tuple, list)):
        for alternative in recipe:
            alternative_recipe = Recipe.get_recipe(alternative, ctx)
            dependencies = alternative_recipe.depends
            if dependencies:
                for dependency in dependencies:
                    if dependency not in recipes:
                        recipes.append(dependency)
            result.append(recipes[:])
            expand_dependencies_recursive(recipes, ctx, result)
            recipes.pop()
    else:
